/* Device-local scores and audio. No imported text is uploaded. */
(function(root){'use strict';let opening;
function open(){if(!opening)opening=new Promise((resolve,reject)=>{if(!root.indexedDB)return reject(Error('Le stockage local est indisponible.'));const request=indexedDB.open('de-vive-voix-library',1);request.onupgradeneeded=()=>{const db=request.result;db.createObjectStore('scores',{keyPath:'id'});db.createObjectStore('audio',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('Impossible d’ouvrir la bibliothèque locale.'));});return opening;}
async function operation(store,mode,action){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),request=action(tx.objectStore(store));tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(Error('Impossible de conserver les fichiers sur cet appareil.'));tx.onabort=()=>reject(Error('La sauvegarde locale a été interrompue.'));});}
const get=(store,id)=>operation(store,'readonly',s=>s.get(id)),put=(store,value)=>operation(store,'readwrite',s=>s.put(value));
async function loadBundle(id,verse){const record=await get('scores',id);if(!record)throw Error('Ce morceau n’est pas présent sur cet appareil. Réimportez son fichier.');const data=record.verses[verse||record.score.verseNumbers[0]];if(!data)throw Error('Couplet absent.');const assets={};for(const [key,list] of Object.entries(data.assets)){assets[key]=[];for(const asset of list){if(asset.cacheId){const cached=await get('audio',asset.cacheId);if(!cached)throw Error('Un son local a disparu. Réimportez le morceau.');assets[key].push({...asset,url:URL.createObjectURL(cached.blob)});}else assets[key].push({...asset});}}return {record,score:record.score,language:data.language||record.score.language,map:data.map,continuations:data.continuations,assets};}
root.PracticeLibrary={open,getAudio:id=>get('audio',id),putAudio:value=>put('audio',value),save:value=>put('scores',value),list:()=>operation('scores','readonly',s=>s.getAll()),loadBundle};if(typeof module!=='undefined')module.exports=root.PracticeLibrary;
})(globalThis);
